/// <summary>
/// Vendor rebate response
/// </summary>
[DataContractAttribute]
public class METVendorRebateResponse extends METBaseResponseContract
{
    VendAccount vendAccount;
    METExternalRebateDealReference metExternalRebateDealReference;
    TAMRebateDealId tamRebateDealId;
    TAMRebateFromDate tamRebateFromDate;
    TAMRebateToDate tamRebateToDate;
    TAMRebateActive tamRebateActive;

}

Method.Source:
[DataMemberAttribute(extendedTypeStr(VendAccount))]
public VendAccount parmVendAccount(VendAccount _vendAccount = vendAccount)
{
    vendAccount = _vendAccount;
    return vendAccount;
}

[DataMemberAttribute(identifierStr(METExternalRebateDealReference))]
public METExternalRebateDealReference parmMETExternalRebateDealReference(METExternalRebateDealReference _metExternalRebateDealReference = metExternalRebateDealReference)
{
    metExternalRebateDealReference = _metExternalRebateDealReference;
    return metExternalRebateDealReference;
}

[DataMemberAttribute(extendedTypeStr(TAMRebateDealId))]
public TAMRebateDealId parmTAMRebateDealId(TAMRebateDealId _tamRebateDealId = tamRebateDealId)
{
    tamRebateDealId = _tamRebateDealId;
    return tamRebateDealId;
}

[DataMemberAttribute(identifierStr(TAMRebateFromDate))]
public TAMRebateFromDate parmTAMRebateFromDate(TAMRebateFromDate _tamRebateFromDate = tamRebateFromDate)
{
    tamRebateFromDate = _tamRebateFromDate;
    return tamRebateFromDate;
}

[DataMemberAttribute(identifierStr(TAMRebateToDate))]
public TAMRebateToDate parmTAMRebateToDate(TAMRebateToDate _tamRebateToDate = tamRebateToDate)
{
    tamRebateToDate = _tamRebateToDate;
    return tamRebateToDate;
}

[DataMemberAttribute(identifierStr(TAMRebateActive))]
public TAMRebateActive parmActive(TAMRebateActive _tamRebateActive = tamRebateActive)
{
    tamRebateActive = _tamRebateActive;
    return tamRebateActive;
}

public static METVendorRebateResponse newFromParameters(METProcessingStatus _result, Description255 _message, VendAccount _vendAccount, METExternalRebateDealReference _metExternalRebateDealReference, TAMRebateDealId _tamRebateDealId, TAMRebateFromDate _tamRebateFromDate, TAMRebateToDate _tamRebateToDate, TAMRebateActive _tamRebateActive)
{
    METVendorRebateResponse response = new METVendorRebateResponse();

    response.parmResult(enum2Symbol(enumNum(METProcessingStatus), enum2int(_result)));
    response.parmMessage(_message);
    response.parmVendAccount(_vendAccount);
    response.parmMETExternalRebateDealReference(_metExternalRebateDealReference);
    response.parmTAMRebateDealId(_tamRebateDealId);
    response.parmTAMRebateFromDate(_tamRebateFromDate);
    response.parmTAMRebateToDate(_tamRebateToDate);
    response.parmActive(_tamRebateActive);

    return response;
}
